   foreach(int value in new[]{0,50,100}){GameState.PlayerCustomData.CustomizeNipple=value;data.Apply();float expected7=value==100?100f:0f,expected8=value==0?100f:0f;Need(Near(data.body.GetBlendShapeWeight(7),expected7)&&Near(data.body.GetBlendShapeWeight(8),expected8),"Original private callback writes actual blend7/8 for"+value);}
   var flat=MCosplay.GetAll().Values.SelectMany(x=>x.GetAll()).First(x=>x.IsFlattenTit);state.PlayerCosplayPartsDict[flat.UniqueId]=true;data.Apply();Need(Flag("isFlattenTit")&&Near(data.body.GetBlendShapeWeight(5),0f),"Original nonempty part loop sets flatten flag and suppresses visible blend5");
  }finally{state.PlayerCostumeDict=costume;state.PlayerCosplayPartsDict=parts;state.PlayerCurrentClothesAState=clothesA;GameState.PlayerCustomData.CustomizeNipple=nipple;data.Apply();}
